//! L'architecture : ce qui tourne où, et pourquoi.
//!
//! Des données, pas du balisage : `crate::doc` est le seul rendu, et une
//! traduction manquante ne compile pas.

use crate::doc::{Block, DlItem, Doc, Tone};

pub static ARCHITECTURE_EN: Doc = Doc {
    title: "Architecture",
    lede: "The decisions that hold the rest up, and the reasoning behind each — including the ones that cost a rewrite to learn.",
    blocks: &[
        Block::P("Most of wisq is unremarkable. These are the parts that are not: places where the obvious approach is wrong, and where knowing why saves the next person a day."),
        Block::P("The page starts with the map — which module holds what, and where the two languages meet — then follows the local machines, the remote protocols, what persists, and how each of these claims is tested."),
        Block::H2("Rust, and one hybrid app"),
        Block::P("Two languages, split by what each part is. The host daemon and the machine core are Rust — a program with no interface, and computation over a byte array; neither has a reason to carry a language runtime. The app is hybrid because it has to be: the interface, the touch model and the remote desktop clients are built on UIKit and Network.framework, which belong to the platform they target. So the app is a Swift shell around a Rust core, and the seam between them is a C ABI of 36 functions, all declared in one file."),
        Block::P("The question for anything new is which of those two it looks like, not which language is nicer to write."),
        Block::H2("No JIT, and never was"),
        Block::P("iOS grants executable memory only to development-signed applications. Every emulator on the App Store is therefore an interpreter, and the ones that pretend otherwise are not on the App Store. That is not a limitation wisq works around — it is the premise. The work went into making the interpreter fast instead."),
        Block::Table { columns: &["Change", "Effect"], rows: &[&["Register file off a Swift array", "2.7× — the optimiser reloaded the buffer after every opaque call"], &["Branch-free immediate sign extension", "+8% — loads and stores are 47% of a Linux boot"], &["Mapped guest RAM instead of cleared", "construction 33–194 ms → under 0.1 ms"], &["Explicit thread quality of service", "keeps the interpreter off efficiency cores"]] },
        Block::P("Three other attempts were measured and reverted: moving cold opcodes out of line cost 9%, unconditional register write-back cost 3%, and a denser dispatch table gained nothing. A negative measurement is worth as much as a positive one and both are in the history."),
        Block::H2("The module map"),
        Block::P("The Swift package is a stack of modules whose dependencies only point down, and the direction matters more than the names: the lower a module sits, the more of it builds and runs on a Linux machine that costs nothing, which is where most of the testing happens. Beside the package sit three Rust crates, each a program or a library in its own right."),
        Block::Table { columns: &["Module", "What it holds", "Why the boundary is there"], rows: &[
            &["WisqCore", "The machine model, persistence, the Keychain, the HID table, the pairing codec", "Imports Foundation, and Security only behind a canImport guard with an in-memory store elsewhere — so the model is tested without a simulator"],
            &["WisqNet", "Byte transport: TCP and TLS over Network.framework, session-long zlib streams, in-memory pipes", "Protocol code talks to a byte stream, never to a socket, so a whole handshake can be tested against scripted bytes"],
            &["WisqRemote", "The RFB/VNC, SPICE and RDP clients, reconnection, the agent client", "Foundation-only, with the platform frameworks behind canImport guards: the Linux CI job builds and tests everything outside those guards"],
            &["WisqVM", "The local machines: the rv32ima and x86-64 cores in Swift, the UART, virtio-blk, snapshots, the terminal grid", "Depends on no other module, not even WisqCore — the emulator builds with no network or persistence code beside it"],
            &["WisqVMRust", "The Swift face of the Rust core: the rv32 machine, the ISO image reader, the driving of the local desktop", "Present only when the Rust core is enabled, and kept apart from the views so that its logic is executed by CI rather than merely compiled"],
            &["WisqUI", "SwiftUI, gestures, rendering, the view models", "iOS only, so no Linux runner compiles it; the one module that sees both the remote and the local side"],
            &["crates/wisq-agent", "The host daemon: a small HTTP server on the standard library, the virsh and demo backends, TLS and pairing", "A separate program on a separate machine; the phone reaches it only through the wire protocol"],
            &["crates/wisq-vm", "The rv32ima interpreter, the x86-64 interpreter and translator, snapshots, the ISO image reader, the C ABI", "Pure computation: one implementation, compiled for the phone, the host tools and the benchmark alike"],
            &["crates/wisq-site", "This site's pages and front end, in Yew", "Pages are data rendered by one module; only two islands are hydrated in the browser"],
        ] },
        Block::P("Two pieces of logic sit lower than the code that calls them, on purpose. MachineLibraryWriter decides the order in which a machine and its secrets are written, and it lives in WisqCore rather than in the view model that uses it: an order can only be shown to matter by making one of its steps fail, and WisqUI is not compiled anywhere such a failure runs in seconds. The local desktop's bridge follows the same reasoning — reading a request, finding the bytes, calling the translator and building the reply is calculation — so it sits beside the Rust core and is judged on Linux at every commit, leaving only the WebKit wiring on the Apple side."),
        Block::H2("The seam, and what crosses it"),
        Block::P("The C ABI is kept deliberately poor, because every type that crosses it is a type two languages have to agree about forever. The machine side is one opaque pointer. The x86-64 translator adds no type at all: bytes in, bytes out, and a few numbers describing what the generated module imports — exposed as functions rather than constants in the header, because a header carries no arithmetic and a literal there would be a second declaration of a number the translator already owns."),
        Block::Ul(&[
            "Threads. wisq_vm_run blocks, and is called from one thread at a time for a given machine; wisq_vm_send and wisq_vm_stop are safe from any thread while it runs. The Swift wrapper is shaped around exactly that contract.",
            "Ownership. A buffer Rust hands out comes back through its own release function — a snapshot through one, translator output through another — because two lifetimes that share a release path invite freeing with the wrong one.",
            "The header is written by hand, which is a liability unless something checks it. C programs under crates/wisq-vm/tests/abi compile against it and link the real static library — one boots a kernel, one translates a region, one attaches a disk and queues keystrokes, one reads an ISO image — and a test names any declaration that no C program calls.",
            "One header, reached in place. The Swift module map points at the crate's own header by relative path instead of keeping a copy: a second copy of a hand-written ABI drifts, and drifts silently.",
            "The one mistake the boundary cannot catch. The region translator takes a base address and an entry offset, both 64 bits wide; C keeps no parameter names at link time, so swapping them compiles, links and runs. Review has to catch it, and the function's own comment says so.",
        ]),
        Block::P("How the library reaches the linker depends on what it is linked into. A bare static archive carries no platform, so on Apple it arrives as an XCFramework — a device slice, plus universal simulator and macOS slices — and Xcode picks the right one; elsewhere it is the plain archive. When neither exists, the package manifest stops and says what to build rather than falling back to the Swift core: a silent fallback would make which interpreter ships depend on what happened to be installed on the machine that built the release."),
        Block::P("The way back is deliberate: WISQ_SWIFT_CORE=1 selects the Swift interpreter, for someone who has Swift and nothing else. CI builds that path on Linux and for the iOS simulator, because an escape hatch that nothing compiles has already rotted."),
        Block::H2("Two rv32 interpreters, held to the same bytes"),
        Block::P("The RISC-V machine is the smallest that boots a real Linux: one RV32 IMA hart with Zicsr, machine and user modes, no MMU, 64 MB of RAM by default, an 8250 UART, a CLINT timer and a syscon. It reimplements the semantics of mini-rv32ima, and it exists twice — once in Swift, once in Rust. The Rust core is about 8% faster over a full boot, so it is the one the app ships with."),
        Block::P("Keeping both is not redundancy for its own sake. Once the faster core became the default, nobody would have exercised the slower one, and a divergence between them would have stopped being noticed. So CI boots the same kernel through both and compares them every million instructions: the count of instructions retired, and the console bytes. The comparison is exact, not statistical — both machines are deterministic, so after the same budget they must have retired the same count and written the same bytes."),
        Block::P("It found a real defect the day it was written. The Rust bus answered reads of the CLINT's mtime with a value taken before the step advanced the clock, so the guest saw a clock one slice late — and late by the whole idle period when the hart had just been woken from WFI. Since the fix, the two cores retire exactly the same instructions and write exactly the same bytes."),
        Block::P("The snapshots are held to the same standard: the Swift and Rust snapshots are compared byte for byte, then each core resumes from the other's and must reach the same future. Without that, the day the app changed cores, every saved machine would have stopped opening."),
        Block::Note { tone: Tone::Info, text: "A trap the comparison script steps around: SwiftPM does not know the Rust archive is an input, so after the library is rebuilt it happily re-runs the previous test binary, linked against the previous library — a pass against code it never saw. The script deletes every test bundle older than the library before running anything." },
        Block::H2("Determinism where it can be had"),
        Block::P("The local machine's virtual clock advances with executed instructions rather than wall time. The same kernel image therefore boots identically on every device and in CI, which is what makes a boot usable as a test — and what lets a benchmark compare two interpreters honestly, because the instruction counts have to match before the throughputs mean anything."),
        Block::H2("The file chooses the core"),
        Block::P("There is no architecture setting. KernelImageKind reads the first 40 KiB of whatever file it is given, and GuestArchitecture derives the core from that. The width is optional, and its absence means \"the file does not say\": the raw image Linux produces for RISC-V has no field that carries it, so an rv32 and an rv64 kernel are indistinguishable there, and a guess would send someone looking in the wrong place."),
        Block::P("The library therefore holds three kinds of file, and no rule on the bytes separates them completely — a compressed kernel and a compressed initramfs are both gzip streams. That fact on the bytes decides the shape of the rest:"),
        Block::Table { columns: &["What the person brings", "What wisq does with it", "Who decides"], rows: &[&["A kernel", "Boots it", "The bytes — KernelImageKind"], &["An initramfs", "Hands it to the kernel, which unpacks it", "The name, then the person — BootMedia"], &["A disk", "Attaches it as /dev/vda", "The person — LocalDisk"]] },
        Block::H2("The x86-64 side has three cores, and the app uses one"),
        Block::P("That count is the most useful thing to know before touching this side. The Swift interpreter is the one the app builds for an x86 guest: memory, an x86-64 core, a 16550 serial port, a pair of 8259 interrupt controllers and a timer, with 256 MB of RAM by default. The Rust interpreter, crates/wisq-vm/src/x86.rs, is not a machine the app boots: it is the processor the translator is tested against, and the one the speed bench measures. The third, x86_wasm.rs, does not interpret at all — it translates a region of guest code into a WebAssembly module."),
        Block::P("Why a translator, when interpretation is the premise. iOS gives no App Store app a page that is both writable and executable, so there is still no JIT — but WebKit may compile WebAssembly, and a module generated at run time is data, not code: the emulator writes a module, and WebKit compiles it. It is the only door, and the translator is what goes through it. Nothing in the app calls it yet: it is driven by tests hosted in the app, inside the simulator, and what remains to wire it is written and costed in the roadmap."),
        Block::P("In CI the generated modules are executed under Bun, which embeds JavaScriptCore — the engine WKWebView uses — and the test refuses to pass silently when that engine is missing: a compiler whose output nothing runs is not a verified compiler."),
        Block::P("The Rust interpreter is built around one idea, lazy flags. x86 sets six flags on almost every arithmetic operation and a program reads a handful; the core keeps only the operation and its two operands, and computes a flag when it is read — what QEMU, Bochs and v86 do, for the same reason."),
        Block::H3("The judge is a real processor"),
        Block::P("None of the three cores judges itself. The oracle files under Tests/Fixtures are recorded on silicon: a script per file has the machine execute each instruction from chosen states and freezes its answer. Where the manual says a flag is undefined, the file freezes nothing — each instruction carries the mask of the flags the architecture guarantees, or the file would be the portrait of one machine, and a core that matched it would be wrong elsewhere. The families recorded so far:"),
        Block::Ul(&[
            "integer arithmetic, logic, shifts, and small whole programs with their memory",
            "branches",
            "the stack and atomic operations",
            "string instructions",
            "scalar floating point",
            "SSE2 integer arithmetic",
            "the XMM registers",
            "the x87 stack",
            "x87 rounding, when the result does not fit",
            "FXSAVE areas",
        ]),
        Block::P("On the general oracle, the two interpreters judge every case. The translator hands back to the host the indirect jumps and calls whose target it cannot predict: a case handed back is a case not judged, not a case failed, and a test refuses that any other family leave the field by that route. Forgetting the third core has turned CI red once already — anything that touches decoding or address computation has to be carried to all three at once."),
        Block::P("The decoder had its own judge before any of this: objdump, with which it agreed on 647 965 instructions — drawn from ls, bash and the system's C library, plus forms assembled on purpose because no compiler emits them — without a single disagreement. The repository keeps a distilled extract, one representative per form."),
        Block::H2("Suspension is a snapshot"),
        Block::P("iOS takes the process back as soon as the screen goes dark, so the question is not whether the local machine is interrupted but what is left of it. A disk would have been the obvious answer and is the wrong one: it keeps files, not the session, and someone coming back wants their shell where they left it, not a second boot. So the state below the kernel is saved whole — the CPU words, the RAM, the input waiting for the guest and the output not yet handed to the console — and restoring it puts the guest back exactly where it was, mid-system-call if that is where it was."),
        Block::P("The format is deliberately dull: a magic, a version, the CPU words, then the RAM, with runs of zeros folded, because the memory of a freshly booted Linux is mostly empty. If the Rust core gains a register, the snapshot code stops compiling: a snapshot that silently omits a field restores a machine that is subtly not the one saved — the worst kind of bug, because it boots. The PC machine uses the same format, and the folding is what makes its 256 MB reasonable to save on every trip to the background: after a full Alpine boot, 22% of its pages are not entirely zero."),
        Block::Ul(&[
            "The two rv32 cores write the same bytes, and each resumes from the other's snapshot.",
            "A truncated file is refused, at every possible truncation, in Rust and in Swift — never a machine half restored.",
            "The first save works: the case an implementation built on \"replace the existing file\" misses, and missed here.",
        ]),
        Block::P("A saved machine is filed under the bytes of its kernel, not its name. Images arrive through Files and nearly all of them are called Image, so two different kernels imported a week apart shared a name and the second inherited the first one's machine. The digest is an FNV-1a computed in the repository rather than a platform hash: a digest that only works where it is not tested is worse than none. And the write is atomic, because the moment it happens is exactly the moment iOS removes the app."),
        Block::H2("The console is incremental"),
        Block::P("The obvious way to render a serial console is to keep every byte and re-derive the visible text on each arrival. That is work proportional to the whole history per chunk — quadratic in the output. Measured: 2 000 lines cost 36.7 seconds of processing, against 0.22 now. The emulator stayed fast while the interface melted, which reads to the user as the VM being slow."),
        Block::P("Being incremental also fixed a real defect. The escape parser now keeps its state between chunks, so a sequence split across two writes is recognised instead of being printed as text."),
        Block::P("The console is a real grid of cells — cursor addressing, erasures, a scroll region, the alternate screen — enough to run an editor, a pager or top, and it serves both cores. One detail bit hard: prompts end without a newline, and an output buffer flushed only on newline kept the prompt invisible exactly when the machine was waiting for the user. It is flushed periodically now."),
        Block::H2("The pixel format is negotiated for rendering, not for the network"),
        Block::P("An RFB client may ask the server for whatever pixel layout it wants. The tempting choice is the one that sends the fewest bytes; the right choice is the one the phone can hand to the graphics stack without touching it. wisq asks for 32 bits little-endian with red at 16, green at 8 and blue at 0, which lands in memory as B, G, R, X — exactly what Core Graphics reads as byteOrder32Little with the first component skipped."),
        Block::H2("CPIXEL is not TPIXEL"),
        Block::P("ZRLE packs colours as CPIXEL, three bytes in the negotiated byte order — B, G, R for the format above. Tight packs them as TPIXEL, which is always R, G, B regardless of what was negotiated. Swapping the two produces a picture that is entirely readable and entirely the wrong colour, with no error anywhere. It is the single easiest way to lose an afternoon in this codebase."),
        Block::H2("zlib streams live as long as the session"),
        Block::P("The compressed encodings share dictionaries across rectangles: a stream is opened once and fed for the life of the connection. One mis-parsed byte does not corrupt one rectangle, it corrupts every frame after it. This is why reconnection builds fresh streams rather than reusing the old ones, and why the decoder is tested against fixtures produced by a reference zlib rather than by itself."),
        Block::P("Tight's JPEG is gated on a decoder. A server may send JPEG only if the client announced a quality level, and wisq announces one only where ImageIO exists; elsewhere a conforming server never sends JPEG, the protocol layer stays testable without an image decoder, and a JPEG that arrives anyway is a named error rather than a guessed rectangle. The order of the encodings it announces depends on the link too: on a fast one ZRLE goes ahead of Tight, because decoding cost then matters more than the last few percent of ratio."),
        Block::H2("SPICE: one connection per channel"),
        Block::P("This is the shape that separates SPICE from RFB next door, and it runs through everything else. RFB is one socket; SPICE is one socket per channel. The main channel opens first because it is the only one that learns the session identifier, and every channel after it must present that identifier as its connection ID. Without it the server does not see a second channel, it sees a second client and gives it a display of its own — a black screen that looks exactly like a broken decoder. It is the most expensive failure in the protocol to diagnose, and it is one line of code."),
        Block::Dl(&[
            DlItem { term: "main", detail: "The session identifier, and the agent: the clipboard, and files sent from the phone into the guest." },
            DlItem { term: "display", detail: "Surfaces, draw operations, images, video streams." },
            DlItem { term: "inputs", detail: "Keyboard and mouse, as PC AT scancodes — SPICE does not take the X11 keysyms RFB does." },
            DlItem { term: "cursor", detail: "The pointer image, on its own connection so that it keeps following the finger while the display channel sends a whole screen of pixels." },
            DlItem { term: "playback", detail: "The guest's sound." },
            DlItem { term: "record", detail: "The phone's microphone." },
        ]),
        Block::P("Everything except display is best effort: a server that does not offer a channel still gives a usable session, and a screen without a keyboard is worth showing. Each channel counts its own serial numbers. The wire is little-endian end to end, so it has its own reader rather than borrowing RFB's big-endian one — which would be wrong in a way that still works most of the time, since a length of one reads the same both ways."),
        Block::P("And the ticket is encrypted with RSA through a closure rather than a direct call. On Apple that means Security; on Linux it means nothing at all. Calling it directly would have put the whole link sequence behind a platform CI does not have; as a closure, the order, the capability negotiation, the framing and every refusal are tested everywhere, and only the encryption itself escapes the stub."),
        Block::H3("The codecs, and what the client asks for"),
        Block::P("The display channel decodes LZ, GLZ, QUIC, LZ4 and JPEG, and the palette forms. A server chooses its image encoding from its own configuration, and the usual default is automatic — QUIC for photographic content, GLZ for graphics — so wisq asks for AUTO_GLZ, the mode servers serve best. The request followed the decoders: LZ while LZ was alone, AUTO_LZ when QUIC arrived, AUTO_GLZ once the GLZ window was wired. Decoding a codec and being sent that codec are two separate successes, and only the second puts a picture on the screen."),
        Block::P("The fixtures are not written by hand. The LZ ones come from the reference encoder linked into a small harness, so a wrong assumption fails a test instead of being confirmed by the person who made it. Two things would have been written wrong from memory, and both were: the LZ stream header is big-endian inside a protocol that is little-endian everywhere else, and match lengths are biased differently for each pixel type — a match then misses one pixel, which gives an image that is almost right, the worst kind of wrong."),
        Block::H3("Three caches, and who evicts"),
        Block::P("The display channel keeps three: the GLZ window, an image cache and a palette cache. Two sizes the client announces sit side by side in one message, and their safe values are opposite — the GLZ window must be large, because below one image the server aborts, while an image cache announced larger than what the client keeps makes the server send names instead of pixels."),
        Block::P("For images and palettes the rule is counter-intuitive: the server evicts and the client obeys. The server keeps its own mirror of what it believes the client holds and announces every eviction; a client that evicted on its own would drift from that mirror, and every drift is a name it can no longer resolve, which draws nothing. So the image cache refuses an image that would exceed its budget rather than evicting to make room. The image evictions ride as a list inside whatever message was leaving anyway, in a header field the decoder had always parsed and nothing had read — harmless while nothing was cached, and not harmless the moment a cache existed."),
        Block::H3("Not implemented is not malformed"),
        Block::P("The pump is built around one distinction. An encoding wisq does not decode leaves that part of the screen alone and is counted; a message that makes no sense stops the pump. Confusing the two disconnects a phone because a server sent a JPEG. What is genuinely missing is named to the user rather than filed under unknown: video stream codecs other than MJPEG — VP8, VP9, H.264, H.265 — and MJPEG itself only where ImageIO exists; compressed audio codecs, Opus and CELT, with only raw PCM passing; and the sound itself plays and records only on Apple platforms, where AVAudioEngine exists. \"The server chose H.264\" is an explanation one can act on; a frozen rectangle is not."),
        Block::H2("RDP: written against a real server"),
        Block::P("RDP is written in Swift, like RFB and SPICE, rather than behind a C bridge to FreeRDP: no framework to build, no CVE trail to follow, nothing to cross-compile — ordinary Swift, tested on Linux and on Apple by the CI that already existed. The reason not to do it had been that nothing seemed verifiable in a Linux container, and that turned out to be false the moment someone tried: xrdp 0.9 and FreeRDP 2.11 both install there, and the whole stack was written against them. In the order it is spoken:"),
        Block::Ol(&[
            "TPKT and X.224 turn TCP into messages, and the security negotiation fits in the first packet: nothing, a choice, or a named refusal. A client that took silence for tacit TLS would be speaking encrypted to a server that is not.",
            "MCS erects the domain, attaches the user and joins the channels; nothing moves until the I/O channel is joined.",
            "The original key exchange, the session keys and the signature on every message — RC4, MD5 and SHA-1, written in the repository because no platform offers them everywhere any more.",
            "Licensing: a server that hands out no licence answers the first message with an alert that means \"move along\", and a client that answers nothing waits there with no explanation.",
            "Capabilities, then the finalisation messages. A negotiation, not a declaration: what follows uses only the intersection, and announcing a capability one does not have makes the server send messages one cannot read.",
            "Screen updates with the interleaved codec, and input.",
        ]),
        Block::P("The interleaved codec is the one MS-RDPEGDI calls RLE, and it is not ordinary RLE: two thirds of its codes describe differences with the line above — a background run copies the previous line, a foreground run copies it with one colour inverted, and a one-bit-per-pixel mask chooses between the two. A decoder that read everything as literal colours would produce a plausible first line and noise below it. It is checked pixel for pixel against FreeRDP's own decoder, on rectangles from a real server, on patterns FreeRDP compressed itself, and on streams crafted for codes its compressor never emits."),
        Block::P("Two translations sit at the edge. RDP sends mouse-button transitions where wisq's input model carries the buttons held, so the session remembers the last state and sends what changed — without that no button would ever be released, and a window would stay stuck to the cursor. And RDP shares SPICE's scancode table but puts the extended-key prefix in a separate flag where SPICE puts it in the value; mixing the two types a keypad key instead of an arrow."),
        Block::Note { tone: Tone::Warn, text: "What is not there: NLA/CredSSP — so the modern Windows versions that require it by default, which wisq does not connect to yet —, virtual channels and with them the clipboard, the remote cursor, mid-session resize, RemoteFX and H.264. The session asks only for RDP's original security, and that security does not authenticate the server: its certificate is signed by a key Microsoft published in 1998. A server that requires TLS or NLA is refused by name — asking for TLS first would mean starting it in the middle of an already open socket, which wisq's transport cannot do today." },
        Block::P("And one decision that still holds: RDP decoding does not go through SPICE's surfaces. The two protocols share a shape — rectangles, codecs, a cursor — and none of their semantics, and grafting one onto the other would make a type with two protocols in its head. If a common layer ever exists, it is the drawing target, not the decoder."),
        Block::H2("The transport"),
        Block::P("Protocol code never sees a socket. A byte stream has two implementations: one over Network.framework, with optional TLS, and one in memory, which lets a complete handshake be tested without opening anything. Network.framework already delivers exactly N bytes when asked for N, so there is no reassembly buffer to get wrong."),
        Block::P("The TCP settings are a value rather than assignments buried in the one file that only compiles on Apple, so they are checked on every machine. Nagle is off, because a keystroke is precisely the one-byte write it would hold back. A connection attempt gives up after 15 seconds. And keepalive is on, for a reason specific to phones: a remote desktop is silent whenever its screen is, carrier NAT and home routers drop idle mappings without telling either end, and the session would look fine until the next touch. Probes start after 60 seconds of silence and repeat every 15, and 4 unanswered ones declare the link dead — so the app can reconnect instead of the person discovering it."),
        Block::P("Reconnection keeps the session and rebuilds the wire. The framebuffer belongs to the reconnecting wrapper and is shared into every connection underneath it, so the renderer's reference survives; everything else, the zlib dictionaries above all, dies with the old connection. The policy is 5 attempts, delays doubling from 1 second up to a ceiling of 30, and a budget refilled only by a connection that stayed up for 10 seconds — because every server reaches ready, including one that completes the handshake and drops a millisecond later, which would otherwise reset the count forever. A wrong password or a failed handshake is never retried."),
        Block::P("What the socket does about security is resolved, not assumed: plain TCP, TLS validated the way the system validates anything else, or TLS accepted only if the leaf certificate hashes to a stored fingerprint. A machine set to pinned with no fingerprint resolves to full system validation — never to a connection that trusts whatever answers, which this case once was. The agent path pins by its own route: the fingerprint recorded at pairing is a required parameter of the agent client, not an option."),
        Block::H2("Persistence and the Keychain"),
        Block::P("The machine list is JSON in the app container, Application Support/Wisq/machines.json, written atomically so that a crash in the middle of a save cannot leave a truncated library. An entry this build cannot decode is carried through untouched rather than dropped: an entry from a newer wisq and a damaged one look exactly alike from here, so only an explicit, confirmed action discards them. A read-modify-write is one trip through the store's serial queue; it used to be two, and a second writer would silently erase the first one's machine."),
        Block::P("Secrets never sit in that file. Passwords go to the Keychain, readable after the first unlock so that a background reconnect works, and bound to this device so that they never ride an iCloud backup. Two rules govern them:"),
        Block::Ul(&[
            "Order. Nothing reaches the credential store before the machine that will point at it is in the list. A secret written ahead of a save that then fails is worse than a lost one: a machine still listed that can no longer log in, or a key that nothing references and nothing will ever clean up.",
            "Reaping. A machine password is keyed by its machine and dies with it; an agent token is keyed by host and port, and shared by every VM on that agent. Deleting a machine removes the keys it used minus the keys the remaining list still points at — deleting one VM on a NAS must not log the others out.",
        ]),
        Block::H2("The touch model is the product"),
        Block::P("A desktop drawn on a phone is unusable if the pointer is your fingertip. wisq draws a virtual cursor on its own layer, offset from the finger, with inertia — so small buttons are reachable and you can see what you are about to hit. Press and release are spaced 50 ms apart and ordered, because guests drop clicks that arrive in the same millisecond."),
        Block::P("Gestures are configurable per machine rather than fixed — the lesson taken from UTM: nobody agrees on what two fingers should do, and the right answer depends mostly on whether the remote desktop fits the phone's screen. The inertia is UIKit's own dynamics rather than an animation loop of wisq's, and because the cursor lives on a layer separate from the pixels it can move at 120 Hz without re-rasterising the desktop."),
        Block::P("Both keyboards go through one invisible view, which stays first responder for the whole session — the condition for receiving a hardware keyboard's keys — and swaps its input view to show or hide the software one. The hardware keyboard reports HID codes; RFB takes X11 keysyms, SPICE and RDP take PC AT scancodes, and the translation is a table rather than a guess: an unknown key sends nothing rather than a guessed code, because a keyboard that lies is worse than one that is incomplete."),
        Block::H2("How it is tested"),
        Block::P("Most of the repository builds on Linux, and that is by design: the lower modules are Foundation-only, so a runner that costs nothing gives real signal on the protocols and the emulation. What needs Apple gets an Apple runner, and what needs WebKit gets an app around it. The jobs the repository's workflows run on every pull request:"),
        Block::Table { columns: &["Job", "What it holds"], rows: &[
            &["Rust (agent + cœur VM)", "Formatting, Clippy with warnings as errors, the Rust tests in release, and the agent built statically for musl, with its size checked against the texts that state it."],
            &["Cœur (Linux)", "Inside the official Swift container: the Rust core built first, then the package; the Swift tests run against the real agent binary and a real kernel; a second build without cargo; both cores benchmarked and compared on the same kernel."],
            &["Cœur (Apple)", "The same package on macOS, for the code behind canImport guards — the JPEG decoder on ImageIO was verified by no job before this one existed."],
            &["Lint", "SwiftLint in strict mode, a guard against anything claiming a licence, and a check that the architectures a release builds are the ones the installer asks for."],
            &["App iOS", "The core packaged as an XCFramework, a real kernel booted through the C ABI inside a simulated iPhone, the Xcode project regenerated and compared with the committed one, the app layer's tests in the simulator, and builds for the simulator on both cores and for a device, unsigned."],
            &["Build site", "Typecheck, build and tests — including the guards on every number the site publishes — and the Heroku build path, run twice."],
        ] },
        Block::P("WisqUI is iOS-only, so no Linux runner compiles it — and two defects in the suspend and resume wiring reached a pull request while that was the whole story: a stop that saved the machine it had just ended, and a machine sent to the background and never picked back up. The app layer's tests now drive the real view model against the real interpreter, on its real thread, writing real files, in a booted simulator on every change."),
        Block::P("WebKit renders in a separate process that iOS does not start for a bare test bundle, so the tests that need a WKWebView — the local desktop's among them — are hosted by the app itself and run in the app job."),
        Block::Note { tone: Tone::Warn, text: "The test kernel is fetched best effort. If that download fails, the boot tests skip, the benchmark stops early and the core comparison only warns — and the run stays green. A last step in both Swift package jobs names every suite that skipped and why, so that a degraded run is visible instead of looking exactly like a complete one." },
        Block::H2("The site itself"),
        Block::P("This site follows the same split. Every page is a Yew component rendered to HTML at build time, so it paints before anything else arrives, and the browser hydrates only two islands — the theme and language controls, and the install prompt. That was a measurement rather than a taste: hydrating whole pages put the prose of every page, in both languages, into the WebAssembly module — 351 822 bytes against 261 252 for the two islands — for text each reader's page already had. A test now refuses any page sentence found in the module."),
        Block::P("The pages are data, not markup: each is a list of blocks rendered by one module, a missing translation does not compile, and a test holds the two languages to the same structure, block for block. Every number this page prints has a line elsewhere in the repository saying where it comes from — the command that remakes it, or why it is not a measurement. The build, the server and the stylesheet stay with Bun, and Heroku builds and serves the site from master."),
    ],
};

pub static ARCHITECTURE_FR: Doc = Doc {
    title: "Architecture",
    lede: "Les décisions qui portent le reste, et le raisonnement derrière chacune — y compris celles qu'il a fallu réécrire pour comprendre.",
    blocks: &[
        Block::P("L'essentiel de wisq est sans surprise. Voici les parties qui ne le sont pas : là où l'approche évidente est fausse, et où savoir pourquoi épargne une journée à la personne suivante."),
        Block::P("La page commence par la carte — quel module porte quoi, et où les deux langages se rejoignent —, puis suit les machines locales, les protocoles distants, ce qui persiste, et la façon dont chacune de ces affirmations est éprouvée."),
        Block::H2("Du Rust, et une application hybride"),
        Block::P("Deux langages, partagés selon ce qu'est chaque partie. Le démon hôte et le cœur des machines sont en Rust — un programme sans interface, et du calcul sur un tableau d'octets ; ni l'un ni l'autre n'a de raison d'embarquer un runtime de langage. L'application est hybride parce qu'elle le doit : l'interface, le modèle tactile et les clients de bureau distant reposent sur UIKit et Network.framework, qui appartiennent à la plateforme qu'ils visent. C'est donc une coquille Swift autour d'un cœur Rust, et la couture entre les deux est une ABI C de 36 fonctions, toutes déclarées dans un seul fichier."),
        Block::P("Pour toute nouveauté, la question est de savoir à laquelle des deux formes elle ressemble, pas quel langage est plus agréable à écrire."),
        Block::H2("Pas de JIT, et il n'y en a jamais eu"),
        Block::P("iOS n'accorde de mémoire exécutable qu'aux applications signées en développement. Tout émulateur sur l'App Store est donc un interpréteur, et ceux qui prétendent le contraire ne sont pas sur l'App Store. Ce n'est pas une limite que wisq contourne — c'est sa prémisse. Le travail est allé à rendre l'interpréteur rapide."),
        Block::Table { columns: &["Changement", "Effet"], rows: &[&["Registres hors du tableau Swift", "2,7× — l'optimiseur rechargeait le tampon après chaque appel opaque"], &["Extension de signe sans branchement", "+8 % — loads et stores font 47 % d'un boot Linux"], &["RAM invitée mappée au lieu d'effacée", "construction 33–194 ms → moins de 0,1 ms"], &["QoS explicite sur le fil d'émulation", "évite que l'interpréteur soit posé sur un cœur d'efficience"]] },
        Block::P("Trois autres tentatives ont été mesurées puis abandonnées : sortir les opcodes froids hors ligne coûtait 9 %, l'écriture arrière inconditionnelle 3 %, et une table de répartition plus dense ne rapportait rien. Une mesure négative vaut autant qu'une positive, et les deux sont dans l'historique."),
        Block::H2("La carte des modules"),
        Block::P("Le paquet Swift est une pile de modules dont les dépendances ne font que descendre, et le sens compte plus que les noms : plus un module est bas, plus il se construit et s'exécute sur une machine Linux qui ne coûte rien, là où se fait l'essentiel des tests. À côté du paquet vivent trois crates Rust, chacune programme ou bibliothèque à part entière."),
        Block::Table { columns: &["Module", "Ce qu'il porte", "Pourquoi la frontière est là"], rows: &[
            &["WisqCore", "Le modèle des machines, la persistance, le trousseau, la table HID, le codec d'appairage", "N'importe que Foundation, et Security seulement derrière une garde canImport, avec un magasin en mémoire ailleurs — le modèle se teste donc sans simulateur"],
            &["WisqNet", "Le transport d'octets : TCP et TLS sur Network.framework, flux zlib de la durée d'une session, tuyaux en mémoire", "Le code protocolaire parle à un flux d'octets, jamais à une socket, donc une poignée de main entière se teste contre des octets scénarisés"],
            &["WisqRemote", "Les clients RFB/VNC, SPICE et RDP, la reconnexion, le client de l'agent", "Foundation seule, les frameworks de plateforme derrière des gardes canImport : le job Linux de la CI construit et teste tout ce qui est hors de ces gardes"],
            &["WisqVM", "Les machines locales : les cœurs rv32ima et x86-64 en Swift, l'UART, virtio-blk, les instantanés, la grille du terminal", "Ne dépend d'aucun autre module, pas même de WisqCore — l'émulateur se construit sans code réseau ni persistance à côté de lui"],
            &["WisqVMRust", "La face Swift du cœur Rust : la machine rv32, le lecteur d'images ISO, la conduite du bureau local", "N'existe que si le cœur Rust est activé, et reste à l'écart des vues pour que sa logique soit exécutée par la CI, pas seulement compilée"],
            &["WisqUI", "SwiftUI, les gestes, le rendu, les modèles de vue", "iOS seulement, donc aucun runner Linux ne le compile ; le seul module qui voit à la fois le distant et le local"],
            &["crates/wisq-agent", "Le démon hôte : un petit serveur HTTP sur la bibliothèque standard, les backends virsh et démo, le TLS et l'appairage", "Un programme à part sur une machine à part ; le téléphone ne l'atteint que par le protocole du fil"],
            &["crates/wisq-vm", "L'interpréteur rv32ima, l'interpréteur et le traducteur x86-64, les instantanés, le lecteur d'images ISO, l'ABI C", "Du calcul pur : une seule implémentation, compilée pour le téléphone, pour les outils hôtes et pour le banc"],
            &["crates/wisq-site", "Les pages et le front de ce site, en Yew", "Les pages sont des données rendues par un seul module ; le navigateur n'hydrate que deux îlots"],
        ] },
        Block::P("Deux morceaux de logique vivent plus bas que le code qui les appelle, et c'est voulu. MachineLibraryWriter fixe l'ordre dans lequel une machine et ses secrets s'écrivent, et il vit dans WisqCore plutôt que dans le modèle de vue qui s'en sert : un ordre ne se montre important qu'en faisant échouer l'une de ses étapes, et WisqUI n'est compilé nulle part où un tel échec s'exécute en quelques secondes. Le pont du bureau local suit le même raisonnement — lire une demande, trouver les octets, appeler le traducteur et former la réponse, c'est du calcul —, donc il vit à côté du cœur Rust et se juge sous Linux à chaque commit, et seul le câblage WebKit reste du côté d'Apple."),
        Block::H2("La couture, et ce qui la traverse"),
        Block::P("L'ABI C est volontairement pauvre, parce que chaque type qui la traverse est un type sur lequel deux langages doivent s'accorder pour toujours. Le côté machine est un pointeur opaque. Le traducteur x86-64 n'ajoute aucun type : des octets en entrée, des octets en sortie, et quelques nombres qui décrivent ce que le module engendré importe — exposés en fonctions plutôt qu'en constantes dans l'en-tête, parce qu'un en-tête ne porte pas d'arithmétique et qu'un littéral y serait une seconde déclaration d'un nombre que le traducteur possède déjà."),
        Block::Ul(&[
            "Les fils. wisq_vm_run bloque, et n'est appelée que depuis un fil à la fois pour une machine donnée ; wisq_vm_send et wisq_vm_stop sont sûres depuis n'importe quel fil pendant qu'elle tourne. L'enrobage Swift est taillé exactement sur ce contrat.",
            "La propriété. Un tampon que Rust cède revient par sa propre fonction de libération — l'instantané par l'une, ce que rend le traducteur par une autre —, parce que deux durées de vie qui partagent un chemin de libération invitent à se tromper de fonction.",
            "L'en-tête est écrit à la main, ce qui est un passif tant que rien ne le vérifie. Des programmes C, sous crates/wisq-vm/tests/abi, se compilent contre lui et se lient à la vraie bibliothèque statique — l'un démarre un noyau, un autre traduit une région, un autre branche un disque et met des frappes en file, un dernier lit une image ISO — et un test nomme toute déclaration qu'aucun programme C n'appelle.",
            "Un seul en-tête, atteint sur place. La carte de module Swift désigne l'en-tête de la crate par un chemin relatif au lieu d'en garder une copie : une seconde copie d'une ABI écrite à la main dérive, et elle dérive en silence.",
            "La seule erreur que la frontière ne peut pas voir. Le traducteur de région prend une adresse de base et un décalage d'entrée, larges de 64 bits tous les deux ; C ne garde aucun nom de paramètre à l'édition des liens, donc les intervertir compile, se lie et s'exécute. C'est à la relecture de l'attraper, et le commentaire de la fonction le dit lui-même.",
        ]),
        Block::P("La façon dont la bibliothèque arrive à l'éditeur de liens dépend de ce dans quoi elle est liée. Une archive statique nue ne porte aucune plateforme : sur Apple, elle arrive donc en XCFramework — une tranche appareil, plus des tranches simulateur et macOS universelles — et Xcode prend la bonne ; ailleurs, c'est l'archive simple. Quand ni l'une ni l'autre n'existe, le manifeste du paquet s'arrête et dit quoi construire plutôt que de retomber sur le cœur Swift : un repli silencieux ferait dépendre l'interpréteur expédié de ce qui se trouvait installé sur la machine qui a construit la version."),
        Block::P("Le chemin du retour est délibéré : WISQ_SWIFT_CORE=1 choisit l'interpréteur Swift, pour qui n'a que Swift. La CI construit ce chemin sous Linux et pour le simulateur iOS, parce qu'une échappatoire que rien ne compile est une échappatoire déjà pourrie."),
        Block::H2("Deux interpréteurs rv32, tenus aux mêmes octets"),
        Block::P("La machine RISC-V est la plus petite qui démarre un vrai Linux : un hart RV32 IMA avec Zicsr, modes machine et utilisateur, pas de MMU, 64 Mo de RAM par défaut, un UART 8250, une horloge CLINT et un syscon. Elle réimplémente la sémantique de mini-rv32ima, et elle existe en deux exemplaires — une fois en Swift, une fois en Rust. Le cœur Rust est plus rapide d'environ 8 % sur un démarrage complet : c'est donc lui que l'application embarque."),
        Block::P("En garder deux n'est pas une redondance pour le principe. Dès que le cœur le plus rapide est devenu le défaut, plus personne n'aurait exercé l'autre, et une divergence entre eux aurait cessé d'être remarquée. La CI fait donc démarrer le même noyau à travers les deux et les compare tous les millions d'instructions : le nombre d'instructions retirées, et les octets de console. La comparaison est exacte, pas statistique — les deux machines sont déterministes, donc après le même budget elles doivent avoir retiré le même compte et écrit les mêmes octets."),
        Block::P("Elle a trouvé un vrai défaut le jour où elle a été écrite. Le bus Rust répondait aux lectures du mtime du CLINT avec une valeur prise avant que le pas n'avance l'horloge : l'invité voyait une horloge en retard d'une tranche — et de toute la période d'inactivité quand le hart venait d'être réveillé d'un WFI. Depuis la correction, les deux cœurs retirent exactement les mêmes instructions et écrivent exactement les mêmes octets."),
        Block::P("Les instantanés sont tenus à la même exigence : ceux du Swift et du Rust sont comparés octet pour octet, puis chaque cœur reprend depuis l'instantané de l'autre et doit arriver au même futur. Sans ça, le jour où l'application a changé de cœur, toutes les machines enregistrées auraient cessé de s'ouvrir."),
        Block::Note { tone: Tone::Info, text: "Un piège que le script de comparaison contourne : SwiftPM ne sait pas que l'archive Rust est une entrée, donc après une reconstruction de la bibliothèque il relance volontiers l'ancien binaire de test, lié à l'ancienne bibliothèque — un succès contre du code qu'il n'a jamais vu. Le script supprime tout paquet de test plus ancien que la bibliothèque avant de lancer quoi que ce soit." },
        Block::H2("Du déterminisme là où il est possible"),
        Block::P("L'horloge virtuelle de la machine locale avance avec les instructions exécutées, pas avec le temps réel. La même image de noyau démarre donc à l'identique sur chaque appareil et en intégration continue, ce qui rend un démarrage utilisable comme test — et permet à un banc de comparer honnêtement deux interpréteurs, car les comptes d'instructions doivent coïncider avant que les débits veuillent dire quelque chose."),
        Block::H2("Le fichier choisit le cœur"),
        Block::P("Il n'y a pas de réglage d'architecture. KernelImageKind lit les premiers 40 Kio du fichier qu'on lui donne, et GuestArchitecture en déduit le cœur. La largeur est facultative, et son absence veut dire « le fichier ne le dit pas » : l'image brute que Linux produit pour RISC-V n'a aucun champ qui la porte, donc un noyau rv32 et un noyau rv64 y sont indiscernables, et deviner enverrait chercher au mauvais endroit."),
        Block::P("La bibliothèque contient donc trois sortes de fichiers, et aucune règle sur les octets ne les sépare complètement — un noyau compressé et un initramfs compressé sont l'un et l'autre un flux gzip. Ce fait sur les octets commande la forme du reste :"),
        Block::Table { columns: &["Ce que la personne apporte", "Ce que wisq en fait", "Qui décide"], rows: &[&["Un noyau", "Il le démarre", "Les octets — KernelImageKind"], &["Un initramfs", "Il le confie au noyau, qui le déballe", "Le nom, puis la personne — BootMedia"], &["Un disque", "Il le branche sur /dev/vda", "La personne — LocalDisk"]] },
        Block::H2("Le côté x86-64 a trois cœurs, et l'application en utilise un"),
        Block::P("Ce compte est le fait le plus utile à connaître avant de toucher à ce côté-là. L'interpréteur Swift est celui que l'application construit pour un invité x86 : de la mémoire, un cœur x86-64, un port série 16550, un couple de contrôleurs d'interruptions 8259 et une horloge, avec 256 Mo de RAM par défaut. L'interpréteur Rust, crates/wisq-vm/src/x86.rs, n'est pas une machine que l'application démarre : c'est le processeur contre lequel le traducteur est éprouvé, et celui que mesure le banc de vitesse. Le troisième, x86_wasm.rs, n'interprète rien du tout — il traduit une région de code invité en module WebAssembly."),
        Block::P("Pourquoi un traducteur, quand l'interprétation est la prémisse. iOS n'accorde à aucune application de l'App Store une page à la fois inscriptible et exécutable, donc toujours pas de JIT — mais WebKit a le droit de compiler du WebAssembly, et un module engendré à l'exécution est une donnée, pas du code : l'émulateur écrit un module, et c'est WebKit qui le compile. C'est la seule porte, et le traducteur est ce qui la franchit. Rien dans l'application ne l'appelle encore : il est conduit par des tests hébergés dans l'application, dans le simulateur, et ce qui manque pour le brancher est écrit et chiffré dans la feuille de route."),
        Block::P("En CI, les modules engendrés s'exécutent sous Bun, qui embarque JavaScriptCore — le moteur de WKWebView — et le test refuse de passer en silence quand ce moteur manque : un compilateur dont rien n'exécute la sortie n'est pas un compilateur vérifié."),
        Block::P("L'interpréteur Rust est bâti autour d'une idée, les drapeaux paresseux. x86 pose six drapeaux à presque chaque opération arithmétique, et un programme en lit une poignée ; le cœur ne garde que l'opération et ses deux opérandes, et ne calcule un drapeau que lorsqu'on le lit — ce que font QEMU, Bochs et v86, pour la même raison."),
        Block::H3("Le juge est un vrai processeur"),
        Block::P("Aucun des trois cœurs ne se juge lui-même. Les fichiers d'oracle de Tests/Fixtures sont relevés sur du silicium : un script par fichier fait exécuter chaque instruction par la machine, depuis des états choisis, et fige sa réponse. Là où le manuel dit qu'un drapeau est indéfini, le fichier ne fige rien — chaque instruction porte le masque des drapeaux que l'architecture garantit, sans quoi le fichier serait le portrait d'une seule machine, et un cœur qui s'y conformerait serait faux ailleurs. Les familles relevées à ce jour :"),
        Block::Ul(&[
            "l'arithmétique entière, la logique, les décalages, et de petits programmes entiers avec leur mémoire",
            "les branchements",
            "la pile et les opérations atomiques",
            "les instructions de chaîne",
            "le flottant scalaire",
            "l'arithmétique entière SSE2",
            "les registres XMM",
            "la pile x87",
            "l'arrondi x87, quand le résultat ne tient pas",
            "les zones FXSAVE",
        ]),
        Block::P("Sur l'oracle général, les deux interpréteurs jugent tous les cas. Le traducteur rend à l'hôte les sauts et appels indirects dont il ne peut pas prédire la cible : un cas rendu est un cas non jugé, pas un cas faux, et un test refuse qu'une autre famille sorte du champ par ce chemin. Oublier le troisième cœur a déjà rougi la CI une fois — ce qui touche au décodage ou au calcul d'adresse doit être porté partout à la fois."),
        Block::P("Le décodeur avait eu son propre juge avant tout cela : objdump, avec lequel il s'est accordé sur 647 965 instructions — tirées de ls, de bash et de la bibliothèque C du système, plus des formes assemblées exprès parce qu'aucun compilateur ne les émet — sans un seul désaccord. Le dépôt en garde un extrait distillé, un représentant par forme."),
        Block::H2("La suspension est un instantané"),
        Block::P("iOS reprend le processus dès que l'écran s'éteint : la question n'est donc pas de savoir si la machine locale est interrompue, mais ce qu'il en reste. Un disque aurait été la réponse évidente, et c'est la mauvaise : il garde les fichiers, pas la session, et qui revient veut son shell là où il l'a laissé, pas un second démarrage. L'état qui est sous le noyau est donc enregistré en entier — les mots du CPU, la RAM, les entrées qui attendent l'invité et la sortie pas encore remise à la console — et le restaurer remet l'invité exactement où il était, au milieu d'un appel système si c'est là qu'il était."),
        Block::P("Le format est volontairement terne : un nombre magique, une version, les mots du CPU, puis la RAM, avec les suites de zéros repliées, parce que la mémoire d'un Linux qui vient de démarrer est surtout vide. Si le cœur Rust gagne un registre, le code de l'instantané cesse de compiler : un instantané qui omet un champ en silence restaure une machine qui n'est subtilement pas celle qu'on a enregistrée — la pire sorte de défaut, parce que cette machine démarre. La machine PC emploie le même format, et le repli est ce qui rend ses 256 Mo raisonnables à enregistrer à chaque passage en arrière-plan : après un démarrage complet d'Alpine, 22 % de ses pages ne sont pas entièrement nulles."),
        Block::Ul(&[
            "Les deux cœurs rv32 écrivent les mêmes octets, et chacun reprend depuis l'instantané de l'autre.",
            "Un fichier tronqué est refusé, à chaque troncature possible, en Rust comme en Swift — jamais une machine à moitié restaurée.",
            "Le premier enregistrement fonctionne : le cas qu'une implémentation bâtie sur « remplacer le fichier existant » rate, et ratait ici.",
        ]),
        Block::P("Une machine enregistrée est classée sous les octets de son noyau, pas sous son nom. Les images arrivent par Fichiers et presque toutes s'appellent Image : deux noyaux différents importés à une semaine d'écart partageaient un nom, et le second héritait de la machine du premier. Le condensé est un FNV-1a calculé dans le dépôt plutôt qu'une fonction de la plateforme : un condensé qui ne fonctionne que là où il n'est pas vérifié est pire que pas de condensé. Et l'écriture est atomique, parce que le moment où elle se produit est exactement celui où iOS retire l'application."),
        Block::H2("La console est incrémentale"),
        Block::P("La façon évidente de rendre une console série est de garder chaque octet et de re-dériver le texte visible à chaque arrivée. C'est un travail proportionnel à tout l'historique par morceau — quadratique dans la sortie. Mesuré : 2 000 lignes coûtaient 36,7 secondes de traitement, contre 0,22 aujourd'hui. L'émulateur restait rapide pendant que l'interface fondait, ce que l'utilisateur lit comme une VM lente."),
        Block::P("Être incrémental a aussi corrigé un vrai défaut : l'analyseur d'échappements garde maintenant son état entre les morceaux, donc une séquence coupée entre deux écritures est reconnue au lieu d'être imprimée telle quelle."),
        Block::P("La console est une vraie grille de cellules — adressage du curseur, effacements, région de défilement, écran alterné —, de quoi faire vivre un éditeur, un pager ou top, et elle sert les deux cœurs. Un détail a mordu : les invites se terminent sans saut de ligne, et un tampon de sortie vidé seulement sur saut de ligne gardait l'invite invisible exactement au moment où la machine attendait l'utilisateur. Il est désormais vidé périodiquement."),
        Block::H2("Le format de pixels est négocié pour le rendu, pas pour le réseau"),
        Block::P("Un client RFB peut demander au serveur la disposition de pixels qu'il veut. Le choix tentant est celui qui envoie le moins d'octets ; le bon est celui que le téléphone peut remettre à la pile graphique sans y toucher. wisq demande du 32 bits petit-boutiste avec le rouge en 16, le vert en 8 et le bleu en 0, ce qui arrive en mémoire sous la forme B, G, R, X — exactement ce que Core Graphics lit en byteOrder32Little avec la première composante ignorée."),
        Block::H2("CPIXEL n'est pas TPIXEL"),
        Block::P("ZRLE encode les couleurs en CPIXEL, trois octets dans l'ordre négocié — B, G, R pour le format ci-dessus. Tight les encode en TPIXEL, qui est toujours R, G, B quel que soit ce qui a été négocié. Intervertir les deux produit une image parfaitement lisible et parfaitement fausse de couleur, sans la moindre erreur nulle part. C'est le moyen le plus simple de perdre un après-midi dans ce dépôt."),
        Block::H2("Les flux zlib vivent aussi longtemps que la session"),
        Block::P("Les encodages compressés partagent leurs dictionnaires d'un rectangle à l'autre : un flux est ouvert une fois et alimenté pendant toute la vie de la connexion. Un octet mal analysé ne corrompt pas un rectangle, il corrompt toutes les images suivantes. D'où des flux neufs à chaque reconnexion plutôt que réutilisés, et un décodeur éprouvé contre des fixtures produites par un zlib de référence plutôt que par lui-même."),
        Block::P("Le JPEG de Tight est verrouillé sur la présence d'un décodeur. Un serveur n'a le droit d'envoyer du JPEG que si le client a annoncé un niveau de qualité, et wisq ne l'annonce que là où ImageIO existe ; ailleurs, un serveur conforme n'envoie jamais de JPEG, la couche protocolaire reste testable sans décodeur d'image, et un JPEG qui arriverait quand même est une erreur nommée, pas un rectangle deviné. L'ordre des encodages annoncés dépend aussi du lien : sur un lien rapide, ZRLE passe devant Tight, parce que le coût de décodage compte alors plus que les derniers pour-cent de ratio."),
        Block::H2("SPICE : une connexion par canal"),
        Block::P("C'est la forme qui sépare SPICE du RFB d'à côté, et elle traverse tout le reste. RFB, c'est une socket ; SPICE, c'est une socket par canal. Le canal principal s'ouvre en premier parce qu'il est le seul à apprendre l'identifiant de session, et chaque canal suivant doit le présenter comme identifiant de connexion. Sans ça, le serveur ne voit pas un second canal : il voit un second client, et lui donne un affichage à lui — un écran noir qui ressemble exactement à un décodeur cassé. C'est la panne la plus coûteuse à diagnostiquer de tout le protocole, et c'est une ligne de code."),
        Block::Dl(&[
            DlItem { term: "principal", detail: "L'identifiant de session, et l'agent : le presse-papiers, et les fichiers envoyés du téléphone vers l'invité." },
            DlItem { term: "display", detail: "Les surfaces, les opérations de dessin, les images, les flux vidéo." },
            DlItem { term: "entrées", detail: "Le clavier et la souris, en scancodes PC AT — SPICE ne prend pas les keysyms X11 que prend RFB." },
            DlItem { term: "curseur", detail: "L'image du pointeur, sur sa propre connexion pour qu'il continue de suivre le doigt pendant que le canal display envoie un écran entier de pixels." },
            DlItem { term: "lecture", detail: "Le son de l'invité." },
            DlItem { term: "enregistrement", detail: "Le micro du téléphone." },
        ]),
        Block::P("Tout sauf le display est en meilleur effort : un serveur qui n'offre pas un canal donne quand même une session utilisable, et un écran sans clavier vaut d'être montré. Chaque canal compte ses propres numéros de série. Le fil est petit-boutiste de bout en bout, donc il a son propre lecteur plutôt que d'emprunter celui, gros-boutiste, de RFB — ce qui serait faux d'une manière qui marcherait quand même la plupart du temps, une longueur de un se lisant pareil dans les deux sens."),
        Block::P("Et le ticket est chiffré en RSA par une fermeture plutôt que par un appel direct. Sur Apple, cela veut dire Security ; sur Linux, cela ne veut rien dire du tout. L'appeler directement aurait mis toute la séquence du lien derrière une plateforme que la CI n'a pas ; en fermeture, l'ordre, la négociation des capacités, le cadrage et chaque refus sont testés partout, et seul le chiffrement lui-même échappe au bouchon."),
        Block::H3("Les codecs, et ce que le client demande"),
        Block::P("Le canal display décode LZ, GLZ, QUIC, LZ4 et JPEG, et les formes à palette. Un serveur choisit son encodage d'image selon sa propre configuration, et le défaut habituel est « automatique » — QUIC pour le photographique, GLZ pour le graphique : wisq demande donc AUTO_GLZ, le mode que les serveurs servent le mieux. La demande a suivi les décodeurs : LZ quand LZ était seul, AUTO_LZ à l'arrivée de QUIC, AUTO_GLZ une fois la fenêtre GLZ branchée. Décoder un codec et se faire envoyer ce codec sont deux réussites distinctes, et seule la seconde met une image à l'écran."),
        Block::P("Les fixtures ne sont pas écrites à la main. Celles de LZ viennent de l'encodeur de référence, lié dans un petit harnais, si bien qu'une hypothèse fausse fait tomber un test au lieu d'être confirmée par celui qui l'a faite. Deux choses se seraient écrites faux de mémoire, et les deux l'ont été : l'en-tête du flux LZ est gros-boutiste dans un protocole petit-boutiste partout ailleurs, et les longueurs de correspondance sont biaisées différemment selon le type de pixel — une correspondance manque alors un pixel, ce qui donne une image presque juste, la pire sorte de faux."),
        Block::H3("Trois caches, et qui évince"),
        Block::P("Le canal display en tient trois : la fenêtre GLZ, un cache d'images et un cache de palettes. Deux tailles que le client annonce voisinent dans le même message, et leurs valeurs sûres sont opposées — la fenêtre GLZ doit être grande, parce qu'en dessous d'une image le serveur s'arrête net, alors qu'un cache d'images annoncé plus grand que ce que le client garde fait envoyer au serveur des noms au lieu de pixels."),
        Block::P("Pour les images et les palettes, la règle va contre l'intuition : le serveur évince, et le client obéit. Le serveur tient son propre miroir de ce qu'il croit que le client garde, et annonce chaque éviction ; un client qui évincerait de lui-même s'écarterait de ce miroir, et chaque écart est un nom qu'il ne sait plus résoudre, donc un dessin perdu. Le cache d'images refuse donc une image qui dépasserait son budget plutôt que d'évincer pour lui faire de la place. Les évictions d'images voyagent en liste à l'intérieur du message qui partait de toute façon, dans un champ d'en-tête que le décodeur lisait depuis toujours et que rien n'exploitait — sans conséquence tant que rien n'était en cache, et plus du tout à la seconde où un cache a existé."),
        Block::H3("« Pas implémenté » n'est pas « malformé »"),
        Block::P("La pompe est bâtie autour d'une distinction. Un encodage que wisq ne décode pas laisse cette partie de l'écran tranquille et se compte ; un message qui n'a pas de sens arrête la pompe. Confondre les deux déconnecte un téléphone parce qu'un serveur a envoyé un JPEG. Ce qui manque vraiment est nommé à l'utilisateur plutôt que rangé sous « inconnu » : les codecs vidéo des flux autres que MJPEG — VP8, VP9, H.264, H.265 —, et MJPEG lui-même seulement là où ImageIO existe ; les codecs audio compressés, Opus et CELT, seul le PCM brut passant ; et le son lui-même ne se joue et ne s'enregistre que sur les plateformes Apple, où AVAudioEngine existe. « Le serveur a choisi H.264 » est une explication sur laquelle on peut agir ; un rectangle figé n'en est pas une."),
        Block::H2("RDP : écrit contre un vrai serveur"),
        Block::P("RDP est écrit en Swift, comme RFB et SPICE, plutôt que derrière une passerelle C vers FreeRDP : pas de framework à construire, pas de CVE à suivre, rien à compiler en croisé — du Swift ordinaire, testé sous Linux comme sur Apple par la CI qui existait déjà. La raison de ne pas le faire était que rien n'en semblait vérifiable dans un conteneur Linux, et elle s'est révélée fausse dès qu'on a essayé : xrdp 0.9 et FreeRDP 2.11 s'y installent tous les deux, et toute la pile a été écrite contre eux. Dans l'ordre où ça se parle :"),
        Block::Ol(&[
            "TPKT et X.224 donnent des messages à TCP, et la négociation de sécurité tient dans le premier paquet : rien, un choix, ou un refus nommé. Un client qui prendrait le silence pour un accord tacite de TLS parlerait chiffré à un serveur qui ne l'est pas.",
            "MCS érige le domaine, attache l'utilisateur et joint les canaux ; rien n'avance tant que le canal d'entrée-sortie n'est pas joint.",
            "L'échange de clés d'origine, les clés de session et la signature de chaque message — RC4, MD5 et SHA-1, écrits dans le dépôt parce qu'aucune plateforme ne les donne plus partout.",
            "La licence : un serveur qui n'en distribue pas répond au premier message par une alerte qui veut dire « passe ton chemin », et un client qui ne répond rien reste là sans explication.",
            "Les capacités, puis les messages de fin. Une négociation, pas une déclaration : la suite n'emploie que l'intersection, et annoncer une capacité qu'on n'a pas fait envoyer au serveur des messages qu'on ne saura pas lire.",
            "Les mises à jour d'écran avec le codec entrelacé, et les entrées.",
        ]),
        Block::P("Le codec entrelacé est celui que MS-RDPEGDI appelle « RLE », et ce n'est pas un RLE ordinaire : deux tiers de ses codes ne décrivent pas des pixels mais des différences avec la ligne du dessus — un « fond » recopie la ligne précédente, une « forme » la recopie en inversant une couleur, et un masque d'un bit par pixel choisit entre les deux. Un décodeur qui lirait tout comme des couleurs littérales produirait une première ligne plausible et du bruit dessous. Il est comparé pixel pour pixel au décodeur de FreeRDP, sur des rectangles d'un vrai serveur, sur des motifs que FreeRDP a comprimés lui-même, et sur des flux fabriqués pour les codes que son compresseur n'émet jamais."),
        Block::P("Deux traductions vivent au bord. RDP envoie des transitions de boutons là où le modèle d'entrées de wisq porte les boutons tenus : la session se souvient de l'état précédent et envoie ce qui a changé — sans quoi aucun bouton ne serait jamais relâché, et une fenêtre resterait accrochée au curseur. Et RDP partage la table de scancodes de SPICE mais met le préfixe des touches étendues dans un drapeau à part, là où SPICE le met dans la valeur ; mélanger les deux tape une touche du pavé numérique à la place d'une flèche."),
        Block::Note { tone: Tone::Warn, text: "Ce qui n'est pas là : NLA/CredSSP — donc les Windows modernes, qui l'exigent par défaut, et auxquels wisq ne se connecte pas encore —, les canaux virtuels et avec eux le presse-papiers, le curseur distant, la renégociation de taille en cours de session, RemoteFX et H.264. La session ne demande que la sécurité d'origine de RDP, et cette sécurité n'authentifie pas le serveur : son certificat est signé par une clé que Microsoft a publiée en 1998. Un serveur qui exige TLS ou NLA est refusé par son nom — demander TLS d'abord supposerait de le démarrer au milieu d'une socket déjà ouverte, ce que le transport de wisq ne sait pas faire aujourd'hui." },
        Block::P("Et une décision qui tient toujours : le décodage RDP ne repasse pas par les surfaces de SPICE. Les deux protocoles partagent la forme — des rectangles, des codecs, un curseur — et rien de leur sémantique ; greffer l'un sur l'autre ferait un type qui a deux protocoles dans la tête. Si une couche commune existe un jour, ce sera la cible de dessin, pas le décodeur."),
        Block::H2("Le transport"),
        Block::P("Le code protocolaire ne voit jamais de socket. Un flux d'octets a deux implémentations : l'une sur Network.framework, avec TLS en option, l'autre en mémoire, qui permet de tester une poignée de main complète sans rien ouvrir. Network.framework livre déjà exactement N octets quand on lui en demande N, donc il n'y a pas de tampon de réassemblage à rater."),
        Block::P("Les réglages TCP sont une valeur plutôt que des affectations enfouies dans le seul fichier qui ne compile que sur Apple : ils se vérifient donc sur toutes les machines. Nagle est coupé, parce qu'une frappe est précisément l'écriture d'un octet qu'il retiendrait. Une tentative de connexion abandonne après 15 secondes. Et le keepalive est actif, pour une raison propre aux téléphones : un bureau distant se tait tant que son écran ne bouge pas, le NAT des opérateurs et les box domestiques effacent les correspondances inactives sans prévenir aucun des deux bouts, et la session aurait l'air saine jusqu'au toucher suivant. Les sondes partent après 60 secondes de silence, se répètent toutes les 15, et 4 restées sans réponse déclarent le lien mort — l'application peut alors se reconnecter au lieu que la personne le découvre."),
        Block::P("La reconnexion garde la session et refait le fil. Le framebuffer appartient à l'enveloppe qui reconnecte et se partage avec chaque connexion en dessous, donc la référence du rendu survit ; tout le reste, les dictionnaires zlib en premier, meurt avec l'ancienne connexion. La politique : 5 tentatives, des délais qui doublent de 1 seconde jusqu'à un plafond de 30, et un budget rechargé seulement par une connexion restée ouverte 10 secondes — parce que tout serveur atteint l'état prêt, y compris celui qui termine la poignée de main et tombe une milliseconde plus tard, et qui sinon remettrait le compte à zéro indéfiniment. Un mauvais mot de passe ou une poignée de main ratée ne sont jamais retentés."),
        Block::P("Ce que la socket fait de la sécurité est résolu, pas supposé : TCP sans chiffrement, TLS validé comme le système valide n'importe quoi d'autre, ou TLS accepté seulement si le certificat feuille a pour condensé une empreinte enregistrée. Une machine réglée sur l'épinglage sans empreinte se résout en validation système complète — jamais en connexion qui fait confiance à quiconque répond, ce que ce cas a été un temps. Le chemin agent épingle par sa propre route : l'empreinte relevée à l'appairage est un paramètre obligatoire du client de l'agent, pas une option."),
        Block::H2("La persistance et le trousseau"),
        Block::P("La liste des machines est du JSON dans le conteneur de l'application, Application Support/Wisq/machines.json, écrit de façon atomique pour qu'un plantage au milieu d'un enregistrement ne laisse pas une bibliothèque tronquée. Une entrée que cette version ne sait pas décoder est gardée telle quelle plutôt que jetée : l'entrée d'un wisq plus récent et une entrée abîmée se ressemblent exactement vues d'ici, donc seule une action explicite, confirmée, les écarte. Une lecture-modification-écriture est un seul passage par la file série du magasin ; elle en faisait deux, et un second écrivain effaçait en silence la machine du premier."),
        Block::P("Les secrets ne sont jamais dans ce fichier. Les mots de passe vont dans le trousseau, lisibles après le premier déverrouillage pour qu'une reconnexion en arrière-plan fonctionne, et liés à cet appareil pour ne jamais voyager dans une sauvegarde iCloud. Deux règles les gouvernent :"),
        Block::Ul(&[
            "L'ordre. Rien n'arrive dans le magasin de secrets avant que la machine qui le désignera soit dans la liste. Un secret écrit avant un enregistrement qui échoue ensuite est pire qu'un secret perdu : une machine toujours listée qui ne peut plus se connecter, ou une clé que rien ne désigne et que rien ne nettoiera jamais.",
            "La récolte. Le mot de passe d'une machine est rangé sous la machine et meurt avec elle ; le jeton d'un agent est rangé sous l'hôte et le port, et partagé par toutes les VM de cet agent. Supprimer une machine retire les clés qu'elle employait, moins celles que la liste restante désigne encore — supprimer une VM d'un NAS ne doit pas déconnecter les autres.",
        ]),
        Block::H2("Le modèle tactile est le produit"),
        Block::P("Un bureau dessiné sur un téléphone est inutilisable si le pointeur est le bout du doigt. wisq dessine un curseur virtuel sur sa propre couche, décalé du doigt, avec de l'inertie — les petits boutons deviennent atteignables et l'on voit ce qu'on s'apprête à toucher. Appui et relâchement sont espacés de 50 ms et ordonnés, parce que les invités perdent les clics qui arrivent dans la même milliseconde."),
        Block::P("Les gestes se règlent par machine plutôt que d'être figés — la leçon tirée d'UTM : personne ne s'accorde sur ce que deux doigts devraient faire, et la bonne réponse dépend surtout de si le bureau distant tient sur l'écran du téléphone. L'inertie est la dynamique d'UIKit plutôt qu'une boucle d'animation maison, et parce que le curseur vit sur une couche séparée des pixels, il peut bouger à 120 Hz sans re-rastériser le bureau."),
        Block::P("Les deux claviers passent par une seule vue invisible, qui reste premier répondeur toute la session — la condition pour recevoir les frappes d'un clavier matériel — et bascule sa vue de saisie pour montrer ou cacher le clavier logiciel. Le clavier matériel rapporte des codes HID ; RFB prend des keysyms X11, SPICE et RDP des scancodes PC AT, et la traduction est une table plutôt qu'une supposition : une touche inconnue n'envoie rien plutôt qu'un code deviné, parce qu'un clavier qui ment est pire qu'un clavier incomplet."),
        Block::H2("Comment c'est testé"),
        Block::P("L'essentiel du dépôt se construit sous Linux, et c'est voulu : les modules du bas sont en Foundation seule, donc un runner qui ne coûte rien donne un vrai signal sur les protocoles et l'émulation. Ce qui demande Apple a un runner Apple, et ce qui demande WebKit a une application autour. Les jobs que les workflows du dépôt lancent sur chaque pull request :"),
        Block::Table { columns: &["Job", "Ce qu'il tient"], rows: &[
            &["Rust (agent + cœur VM)", "La mise en forme, Clippy avec les avertissements en erreurs, les tests Rust en release, et l'agent construit statiquement pour musl, sa taille comparée aux textes qui l'annoncent."],
            &["Cœur (Linux)", "Dans le conteneur Swift officiel : le cœur Rust construit d'abord, puis le paquet ; les tests Swift lancés contre le vrai binaire de l'agent et un vrai noyau ; une seconde construction sans cargo ; les deux cœurs mesurés au banc et comparés sur le même noyau."],
            &["Cœur (Apple)", "Le même paquet sur macOS, pour le code derrière les gardes canImport — le décodeur JPEG sur ImageIO n'était vérifié par aucun job avant que celui-ci existe."],
            &["Lint", "SwiftLint en mode strict, une garde contre toute revendication de licence, et une vérification que les architectures qu'une version construit sont celles que l'installateur demande."],
            &["App iOS", "Le cœur empaqueté en XCFramework, un vrai noyau démarré à travers l'ABI C dans un iPhone simulé, le projet Xcode régénéré et comparé à celui du dépôt, les tests de la couche application dans le simulateur, et des constructions pour le simulateur sur les deux cœurs et pour un appareil, sans signature."],
            &["Build site", "Vérification des types, construction et tests — dont les gardes sur chaque nombre que le site publie —, et le chemin de construction de Heroku, lancé deux fois."],
        ] },
        Block::P("WisqUI est réservé à iOS, donc aucun runner Linux ne le compile — et deux défauts du câblage de la suspension et de la reprise ont atteint une pull request tant que c'était toute l'histoire : un arrêt qui enregistrait la machine qu'il venait de terminer, et une machine mise en arrière-plan et jamais reprise. Les tests de la couche application font désormais tourner le vrai modèle de vue contre le vrai interpréteur, sur son vrai fil, en écrivant de vrais fichiers, dans un simulateur démarré, à chaque changement."),
        Block::P("WebKit rend dans un processus séparé qu'iOS ne démarre pas pour un paquet de tests nu : les tests qui ont besoin d'un WKWebView — ceux du bureau local compris — sont donc hébergés par l'application elle-même, et tournent dans le job de l'application."),
        Block::Note { tone: Tone::Warn, text: "Le noyau de test est récupéré en « best effort ». Si ce téléchargement échoue, les tests de démarrage sautent, le banc s'arrête tôt et la comparaison des cœurs se contente d'un avertissement — et l'exécution reste verte. Une dernière étape des deux jobs du paquet Swift nomme chaque suite qui a sauté, et pourquoi, pour qu'une exécution dégradée se voie au lieu de ressembler exactement à une exécution complète." },
        Block::H2("Le site lui-même"),
        Block::P("Ce site suit le même partage. Chaque page est un composant Yew rendu en HTML à la construction, si bien qu'elle s'affiche avant que quoi que ce soit d'autre arrive, et le navigateur n'hydrate que deux îlots — les réglages de thème et de langue, et l'invite d'installation. C'était une mesure, pas un goût : hydrater les pages entières mettait dans le module WebAssembly la prose de toutes les pages, dans les deux langues — 351 822 octets contre 261 252 pour les deux îlots — pour un texte que la page de chaque lecteur avait déjà. Un test refuse désormais toute phrase de page trouvée dans le module."),
        Block::P("Les pages sont des données, pas du balisage : chacune est une liste de blocs rendue par un seul module, une traduction manquante ne compile pas, et un test tient les deux langues à la même structure, bloc pour bloc. Chaque nombre que cette page imprime a, ailleurs dans le dépôt, une ligne qui dit d'où il vient — la commande qui le refait, ou la raison pour laquelle ce n'est pas une mesure. La construction, le serveur et la feuille de style restent à Bun, et Heroku construit et sert le site depuis master."),
    ],
};
